contract InvMutTest {
    C c;
    bool private acceptEther = true;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool accept) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        acceptEther = accept;
        require(address(this).balance >= 100);

        bool reverted;
        c.getFirstWithdrawalBonus(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!(accept) || !reverted);
    }

    receive() external payable {
        if (!acceptEther) revert();
    }
}

