// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;
    bool private acceptEther = true;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(bool accept) internal {
        vm.deal(address(c), VALUE_CAP);
        acceptEther = accept;
        vm.assume(address(this).balance >= 100);
        bool reverted;
        try c.getFirstWithdrawalBonus(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!(accept) || !reverted);
    }

    function testFuzz_run(bool accept) public {
        _run(accept);
    }

    receive() external payable {
        if (!acceptEther) revert();
    }
}
